 19→// cursorChatArchive is the portable archive format for Cursor agent chat sessions.
 20→// Shared by both cursor-export and cursor-import commands.
 21→type cursorChatArchive struct {
 22→	Format         string            `json:"format"`
 23→	Version        int               `json:"version"`
 24→	AgentID        string            `json:"agentId"`
 25→	DBPath         string            `json:"db_path"`
 26→	TranscriptPath string            `json:"transcript_path,omitempty"`
 27→	Store          cursorStoreData   `json:"store"`
 28→	Transcript     []json.RawMessage `json:"transcript,omitempty"`
 29→}
 30→
 31→type cursorStoreData struct {
 32→	Meta  map[string]string `json:"meta"`
 33→	Blobs map[string]string `json:"blobs"`
 34→}
