 36→func newCursorExportCmd() *cobra.Command {
 37→	return &cobra.Command{
 38→		Use:   "cursor-export <agent-id> [output-path]",
 39→		Short: "Export a Cursor agent chat session to a portable archive",
 40→		Long: `Export a Cursor agent chat session (store.db + transcript) to a single
 41→.cursor-chat.json file that can be imported on another machine.
 42→
 43→Searches ~/.cursor/chats/ for the store.db and ~/.cursor/projects/ for
 44→the agent transcript JSONL.`,
 45→		Args: cobra.RangeArgs(1, 2),
 46→		RunE: func(cmd *cobra.Command, args []string) error {
 47→			agentID := args[0]
 48→			outputPath := agentID + ".cursor-chat.json"
 49→			if len(args) > 1 {
 50→				outputPath = args[1]
 51→			}
 52→			return runCursorExport(cmd, agentID, outputPath)
 53→		},
 54→	}
 55→}
