 57→func runCursorExport(cmd *cobra.Command, agentID, outputPath string) error {
 58→	w := cmd.OutOrStdout()
 59→	ctx := cmd.Context()
 60→	homeDir, err := os.UserHomeDir()
 61→	if err != nil {
 62→		return fmt.Errorf("getting home directory: %w", err)
 63→	}
 64→
 65→	cursorDir := filepath.Join(homeDir, ".cursor")
 66→	chatsDir := filepath.Join(cursorDir, "chats")
 67→	projectsDir := filepath.Join(cursorDir, "projects")
 68→
 69→	// Find store.db
 70→	dbPath, err := findCursorFile(filepath.Join(chatsDir, "*", agentID, "store.db"))
 71→	if err != nil {
 72→		return fmt.Errorf("finding store.db for agent %s: %w", agentID, err)
 73→	}
 74→	if dbPath == "" {
 75→		return fmt.Errorf("no store.db found for agent %q (searched %s/*/%s/store.db)", agentID, chatsDir, agentID)
 76→	}
 77→	fmt.Fprintf(w, "Found database: %s\n", dbPath)
 78→
 79→	// Export database
 80→	storeData, err := exportCursorDB(ctx, dbPath)
 81→	if err != nil {
 82→		return fmt.Errorf("exporting database: %w", err)
 83→	}
 84→	fmt.Fprintf(w, "Exported %d meta rows, %d blobs\n", len(storeData.Meta), len(storeData.Blobs))
 85→
 86→	// Find transcript
 87→	transcriptPath, err := findCursorFile(filepath.Join(projectsDir, "*", "agent-transcripts", agentID+".jsonl"))
 88→	if err != nil {
 89→		return fmt.Errorf("searching for transcript: %w", err)
 90→	}
 91→
 92→	archive := cursorChatArchive{
 93→		Format:  "cursor-chat-export",
 94→		Version: 1,
 95→		AgentID: agentID,
 96→		DBPath:  dbPath,
 97→		Store:   storeData,
 98→	}
 99→
100→	if transcriptPath != "" {
101→		fmt.Fprintf(w, "Found transcript: %s\n", transcriptPath)
102→		archive.TranscriptPath = transcriptPath
103→
104→		transcript, err := readCursorTranscript(transcriptPath)
105→		if err != nil {
106→			return fmt.Errorf("reading transcript: %w", err)
107→		}
108→		archive.Transcript = transcript
109→		fmt.Fprintf(w, "Exported %d transcript entries\n", len(transcript))
110→	} else {
111→		fmt.Fprintln(w, "No transcript JSONL found (exporting without it)")
112→	}
113→
114→	data, err := json.Marshal(archive)
115→	if err != nil {
116→		return fmt.Errorf("marshaling archive: %w", err)
117→	}
118→
119→	if err := os.WriteFile(outputPath, data, 0o600); err != nil {
120→		return fmt.Errorf("writing archive: %w", err)
121→	}
122→
123→	info, err := os.Stat(outputPath)
124→	if err != nil {
125→		return fmt.Errorf("stat output file: %w", err)
126→	}
127→	sizeMB := float64(info.Size()) / (1024 * 1024)
128→	fmt.Fprintf(w, "\nExported to: %s (%.2f MB)\n", outputPath, sizeMB)
129→	return nil
130→}
