132→func findCursorFile(pattern string) (string, error) {
133→	matches, err := filepath.Glob(pattern)
134→	if err != nil {
135→		return "", fmt.Errorf("glob %s: %w", pattern, err)
136→	}
137→	if len(matches) == 0 {
138→		return "", nil
139→	}
140→	return matches[0], nil
141→}
