143→func exportCursorDB(ctx context.Context, dbPath string) (cursorStoreData, error) {
144→	db, err := sql.Open("sqlite", dbPath)
145→	if err != nil {
146→		return cursorStoreData{}, fmt.Errorf("opening database: %w", err)
147→	}
148→	defer db.Close()
149→
150→	// Flush WAL to main database file
151→	if _, err := db.ExecContext(ctx, "PRAGMA wal_checkpoint(PASSIVE)"); err != nil {
152→		return cursorStoreData{}, fmt.Errorf("WAL checkpoint: %w", err)
153→	}
154→
155→	meta := make(map[string]string)
156→	metaRows, err := db.QueryContext(ctx, "SELECT key, value FROM meta")
157→	if err != nil {
158→		return cursorStoreData{}, fmt.Errorf("querying meta: %w", err)
159→	}
160→	defer metaRows.Close()
161→	for metaRows.Next() {
162→		var key, value string
163→		if err := metaRows.Scan(&key, &value); err != nil {
164→			return cursorStoreData{}, fmt.Errorf("scanning meta row: %w", err)
165→		}
166→		meta[key] = value
167→	}
168→	if err := metaRows.Err(); err != nil {
169→		return cursorStoreData{}, fmt.Errorf("iterating meta rows: %w", err)
170→	}
171→
172→	blobs := make(map[string]string)
173→	blobRows, err := db.QueryContext(ctx, "SELECT id, data FROM blobs")
174→	if err != nil {
175→		return cursorStoreData{}, fmt.Errorf("querying blobs: %w", err)
176→	}
177→	defer blobRows.Close()
178→	for blobRows.Next() {
179→		var id string
180→		var data []byte
181→		if err := blobRows.Scan(&id, &data); err != nil {
182→			return cursorStoreData{}, fmt.Errorf("scanning blob row: %w", err)
183→		}
184→		blobs[id] = base64.StdEncoding.EncodeToString(data)
185→	}
186→	if err := blobRows.Err(); err != nil {
187→		return cursorStoreData{}, fmt.Errorf("iterating blob rows: %w", err)
188→	}
189→
190→	return cursorStoreData{Meta: meta, Blobs: blobs}, nil
191→}
192→
193→func readCursorTranscript(path string) ([]json.RawMessage, error) {
194→	data, err := os.ReadFile(path) //nolint:gosec // path is constructed from glob results, not user input
195→	if err != nil {
196→		return nil, fmt.Errorf("reading transcript file: %w", err)
197→	}
198→
199→	var entries []json.RawMessage
200→	dec := json.NewDecoder(bytes.NewReader(data))
201→	for dec.More() {
202→		var raw json.RawMessage
203→		if err := dec.Decode(&raw); err != nil {
204→			return nil, fmt.Errorf("decoding transcript line: %w", err)
205→		}
206→		entries = append(entries, raw)
207→	}
208→	return entries, nil
209→}
