 23→// CursorAgent implements the Agent interface for Cursor.
 24→//
 25→//nolint:revive // CursorAgent is clearer than Agent in this context
 26→type CursorAgent struct{}
 27→
 28→// NewCursorAgent creates a new Cursor agent instance.
 29→func NewCursorAgent() agent.Agent {
 30→	return &CursorAgent{}
 31→}
