 50→// DetectPresence checks if Cursor is configured in the repository.
 51→func (c *CursorAgent) DetectPresence(ctx context.Context) (bool, error) {
 52→	worktreeRoot, err := paths.WorktreeRoot(ctx)
 53→	if err != nil {
 54→		worktreeRoot = "."
 55→	}
 56→
 57→	cursorDir := filepath.Join(worktreeRoot, ".cursor")
 58→	if _, err := os.Stat(cursorDir); err == nil {
 59→		return true, nil
 60→	}
 61→	return false, nil
 62→}
 63→
 64→// GetSessionID extracts the session ID from hook input.
 65→func (c *CursorAgent) GetSessionID(input *agent.HookInput) string {
 66→	return input.SessionID
 67→}
 68→
 69→// ResolveSessionFile returns the path to a Cursor session file.
 70→// Cursor IDE uses a nested layout: <dir>/<id>/<id>.jsonl
 71→// Cursor CLI uses a flat layout: <dir>/<id>.jsonl
 72→// We prefer nested if the file OR directory exists (the directory may be created
 73→// before the file is flushed), otherwise fall back to flat.
 74→func (c *CursorAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 75→	nestedDir := filepath.Join(sessionDir, agentSessionID)
 76→	nested := filepath.Join(nestedDir, agentSessionID+".jsonl")
 77→	if _, err := os.Stat(nested); err == nil {
 78→		return nested
 79→	}
 80→	// IDE creates the directory before the transcript file — predict nested path.
 81→	if info, err := os.Stat(nestedDir); err == nil && info.IsDir() {
 82→		return nested
 83→	}
 84→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
 85→}
 86→
 87→// ProtectedDirs returns directories that Cursor uses for config/state.
 88→func (c *CursorAgent) ProtectedDirs() []string { return []string{".cursor"} }
 89→
 90→// GetSessionDir returns the directory where Cursor stores session transcripts.
 91→func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
 92→	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
 93→		return override, nil
 94→	}
 95→
 96→	homeDir, err := os.UserHomeDir()
 97→	if err != nil {
 98→		return "", fmt.Errorf("failed to get home directory: %w", err)
 99→	}
100→
101→	projectDir := sanitizePathForCursor(repoPath)
102→	return filepath.Join(homeDir, ".cursor", "projects", projectDir, "agent-transcripts"), nil
103→}
104→
105→// ReadSession reads a session from Cursor's storage (JSONL transcript file).
106→// Note: ModifiedFiles is left empty because Cursor's transcript format does not
107→// contain tool_use blocks. File detection relies on git status instead.
108→func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
109→	if input.SessionRef == "" {
110→		return nil, errors.New("session reference (transcript path) is required")
111→	}
112→
113→	data, err := os.ReadFile(input.SessionRef)
114→	if err != nil {
115→		return nil, fmt.Errorf("failed to read transcript: %w", err)
116→	}
117→
118→	return &agent.AgentSession{
119→		SessionID:  input.SessionID,
120→		AgentName:  c.Name(),
121→		SessionRef: input.SessionRef,
122→		StartTime:  time.Now(),
123→		NativeData: data,
124→	}, nil
125→}
126→
127→// WriteSession writes a session to Cursor's storage (JSONL transcript file).
128→func (c *CursorAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
129→	if session == nil {
130→		return errors.New("session is nil")
131→	}
132→
133→	if session.AgentName != "" && session.AgentName != c.Name() {
134→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
135→	}
136→
137→	if session.SessionRef == "" {
138→		return errors.New("session reference (transcript path) is required")
139→	}
140→
141→	if len(session.NativeData) == 0 {
142→		return errors.New("session has no native data to write")
143→	}
144→
145→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
146→		return fmt.Errorf("failed to write transcript: %w", err)
147→	}
148→
149→	return nil
150→}
