152→// FormatResumeCommand returns an instruction to resume a Cursor session.
153→// Cursor is a GUI IDE, so there's no CLI command to resume a session directly.
154→func (c *CursorAgent) FormatResumeCommand(_ string) string {
155→	return "Open this project in Cursor to continue the session."
156→}
