  1→package cli
  2→
  3→import (
  4→	"context"
  5→	"crypto/md5" //nolint:gosec // MD5 used to match Cursor's directory naming, not for security
  6→	"database/sql"
  7→	"encoding/base64"
  8→	"encoding/hex"
  9→	"encoding/json"
 10→	"fmt"
