 17→func newCursorImportCmd() *cobra.Command {
 18→	var (
 19→		workspaceHash string
 20→		projectSlug   string
 21→		force         bool
 22→	)
 23→
 24→	cmd := &cobra.Command{
 25→		Use:   "cursor-import <archive-file>",
 26→		Short: "Import a Cursor agent chat session from a portable archive",
 27→		Long: `Import a Cursor agent chat session from a .cursor-chat.json archive file.
 28→
 29→Recreates the store.db and transcript JSONL in the appropriate
 30→Cursor directories (~/.cursor/chats/ and ~/.cursor/projects/).
 31→
 32→By default, the workspace hash is computed as MD5 of the current directory
 33→(matching Cursor's convention). Override with --workspace-hash if needed.`,
 34→		Args: cobra.ExactArgs(1),
 35→		RunE: func(cmd *cobra.Command, args []string) error {
 36→			return runCursorImport(cmd, args[0], workspaceHash, projectSlug, force)
 37→		},
 38→	}
 39→
 40→	cmd.Flags().StringVar(&workspaceHash, "workspace-hash", "", "override the workspace hash (subfolder under ~/.cursor/chats/)")
 41→	cmd.Flags().StringVar(&projectSlug, "project-slug", "", "override the project slug (subfolder under ~/.cursor/projects/)")
 42→	cmd.Flags().BoolVar(&force, "force", false, "overwrite existing files without prompting")
 43→
 44→	return cmd
 45→}
 46→
 47→func runCursorImport(cmd *cobra.Command, archivePath, workspaceHash, projectSlug string, force bool) error {
 48→	w := cmd.OutOrStdout()
 49→	ctx := cmd.Context()
 50→
 51→	data, err := os.ReadFile(archivePath) //nolint:gosec // archivePath is a CLI argument, not user-controlled web input
 52→	if err != nil {
 53→		return fmt.Errorf("reading archive: %w", err)
 54→	}
 55→
 56→	var archive cursorChatArchive
 57→	if err := json.Unmarshal(data, &archive); err != nil {
 58→		return fmt.Errorf("parsing archive: %w", err)
 59→	}
 60→
 61→	if archive.Format != "cursor-chat-export" {
 62→		return fmt.Errorf("not a valid cursor-chat-export file (format: %q)", archive.Format)
 63→	}
 64→
 65→	agentID := archive.AgentID
 66→	fmt.Fprintf(w, "Importing agent: %s\n", agentID)
 67→
 68→	homeDir, err := os.UserHomeDir()
 69→	if err != nil {
 70→		return fmt.Errorf("getting home directory: %w", err)
 71→	}
 72→
 73→	cursorDir := filepath.Join(homeDir, ".cursor")
 74→	chatsDir := filepath.Join(cursorDir, "chats")
 75→	projectsDir := filepath.Join(cursorDir, "projects")
 76→
 77→	// Determine workspace hash: MD5 of current directory (Cursor's convention)
 78→	if workspaceHash == "" {
 79→		cwd, err := os.Getwd() //nolint:forbidigo // need actual cwd for Cursor's MD5(project_path) hash, not git root
 80→		if err != nil {
 81→			return fmt.Errorf("getting current directory: %w", err)
 82→		}
 83→		workspaceHash = cursorWorkspaceHash(cwd)
 84→		fmt.Fprintf(w, "Workspace hash: %s (from %s)\n", workspaceHash, cwd)
 85→	}
 86→
 87→	// Import store.db
 88→	dbTarget := filepath.Join(chatsDir, workspaceHash, agentID, "store.db")
 89→	fmt.Fprintf(w, "Target database: %s\n", dbTarget)
 90→
 91→	if fileExists(dbTarget) && !force {
 92→		return fmt.Errorf("%s already exists; use --force to overwrite", dbTarget)
 93→	}
 94→
 95→	if err := importCursorDB(ctx, archive.Store, dbTarget, force); err != nil {
 96→		return fmt.Errorf("importing database: %w", err)
 97→	}
 98→	fmt.Fprintf(w, "Imported %d meta rows, %d blobs\n", len(archive.Store.Meta), len(archive.Store.Blobs))
 99→
100→	// Import transcript if present
101→	if len(archive.Transcript) > 0 {
102→		slug := projectSlug
103→		if slug == "" {
104→			cwd, err := os.Getwd() //nolint:forbidigo // need actual cwd for Cursor's MD5(project_path) hash, not git root
105→			if err != nil {
106→				return fmt.Errorf("getting current directory: %w", err)
107→			}
108→			slug = cursorWorkspaceHash(cwd)
109→		}
110→
111→		transcriptTarget := filepath.Join(projectsDir, slug, "agent-transcripts", agentID+".jsonl")
112→		fmt.Fprintf(w, "Target transcript: %s\n", transcriptTarget)
113→
114→		if fileExists(transcriptTarget) && !force {
115→			return fmt.Errorf("%s already exists; use --force to overwrite", transcriptTarget)
116→		}
117→
118→		if err := importCursorTranscript(archive.Transcript, transcriptTarget); err != nil {
119→			return fmt.Errorf("importing transcript: %w", err)
120→		}
121→		fmt.Fprintf(w, "Imported %d transcript entries\n", len(archive.Transcript))
122→	} else {
123→		fmt.Fprintln(w, "No transcript in archive, skipping.")
124→	}
125→
126→	fmt.Fprintf(w, "\nImport complete for agent %s\n", agentID)
127→	return nil
128→}
