130→// cursorWorkspaceHash computes the workspace hash Cursor uses for directory naming.
131→// Cursor stores per-project data under MD5(absolute_project_path).
132→func cursorWorkspaceHash(projectPath string) string {
133→	sum := md5.Sum([]byte(projectPath)) //nolint:gosec // matching Cursor's convention, not used for security
134→	return hex.EncodeToString(sum[:])
135→}
