137→func importCursorDB(ctx context.Context, store cursorStoreData, targetPath string, force bool) error {
138→	if err := os.MkdirAll(filepath.Dir(targetPath), 0o750); err != nil {
139→		return fmt.Errorf("creating directory: %w", err)
140→	}
141→
142→	if force {
143→		// Remove existing DB and WAL/SHM files (errors ignored; files may not exist)
144→		_ = os.Remove(targetPath)
145→		_ = os.Remove(targetPath + "-wal")
146→		_ = os.Remove(targetPath + "-shm")
147→	}
148→
149→	db, err := sql.Open("sqlite", targetPath)
150→	if err != nil {
151→		return fmt.Errorf("creating database: %w", err)
152→	}
153→	defer db.Close()
154→
155→	if _, err := db.ExecContext(ctx, "PRAGMA journal_mode=wal"); err != nil {
156→		return fmt.Errorf("setting journal mode: %w", err)
157→	}
158→
159→	if _, err := db.ExecContext(ctx, "CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT)"); err != nil {
160→		return fmt.Errorf("creating meta table: %w", err)
161→	}
162→	if _, err := db.ExecContext(ctx, "CREATE TABLE blobs (id TEXT PRIMARY KEY, data BLOB)"); err != nil {
163→		return fmt.Errorf("creating blobs table: %w", err)
164→	}
165→
166→	tx, err := db.BeginTx(ctx, nil)
167→	if err != nil {
168→		return fmt.Errorf("beginning transaction: %w", err)
169→	}
170→	defer tx.Rollback() //nolint:errcheck // rollback after commit is a no-op
171→
172→	for key, value := range store.Meta {
173→		if _, err := tx.ExecContext(ctx, "INSERT INTO meta (key, value) VALUES (?, ?)", key, value); err != nil {
174→			return fmt.Errorf("inserting meta key %q: %w", key, err)
175→		}
176→	}
177→
178→	for id, b64Data := range store.Blobs {
179→		data, err := base64.StdEncoding.DecodeString(b64Data)
180→		if err != nil {
181→			return fmt.Errorf("decoding blob %q: %w", id, err)
182→		}
183→		if _, err := tx.ExecContext(ctx, "INSERT INTO blobs (id, data) VALUES (?, ?)", id, data); err != nil {
184→			return fmt.Errorf("inserting blob %q: %w", id, err)
185→		}
186→	}
187→
188→	if err := tx.Commit(); err != nil {
189→		return fmt.Errorf("committing transaction: %w", err)
190→	}
191→	return nil
192→}
193→
194→func importCursorTranscript(entries []json.RawMessage, targetPath string) error {
195→	if err := os.MkdirAll(filepath.Dir(targetPath), 0o750); err != nil {
196→		return fmt.Errorf("creating directory: %w", err)
197→	}
198→
199→	f, err := os.OpenFile(targetPath, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o600) //nolint:gosec // targetPath is constructed from known paths
200→	if err != nil {
201→		return fmt.Errorf("creating file: %w", err)
202→	}
203→	defer f.Close()
204→
205→	for _, entry := range entries {
