949→// addDirectoryToChanges walks a filesystem directory and returns TreeChange entries
950→// for each file, suitable for use with ApplyTreeChanges.
951→// dirPathAbs is the absolute filesystem path; dirPathRel is the git tree-relative path.
952→func addDirectoryToChanges(repo *git.Repository, dirPathAbs, dirPathRel string) ([]TreeChange, error) {
953→	var changes []TreeChange
954→	err := filepath.Walk(dirPathAbs, func(path string, info os.FileInfo, err error) error {
955→		if err != nil {
956→			return err
957→		}
958→
959→		// Skip symlinks (same security rationale as addDirectoryToEntriesWithAbsPath)
960→		linfo, lstatErr := os.Lstat(path)
961→		if lstatErr != nil {
962→			return fmt.Errorf("failed to lstat %s: %w", path, lstatErr)
963→		}
964→		if linfo.Mode()&os.ModeSymlink != 0 {
965→			if info.IsDir() {
966→				return filepath.SkipDir
967→			}
968→			return nil
969→		}
970→
971→		if info.IsDir() {
972→			return nil
973→		}
974→
975→		relWithinDir, relErr := filepath.Rel(dirPathAbs, path)
976→		if relErr != nil {
977→			return fmt.Errorf("failed to get relative path for %s: %w", path, relErr)
978→		}
979→		if strings.HasPrefix(relWithinDir, "..") {
980→			return fmt.Errorf("path traversal detected: %s", relWithinDir)
981→		}
982→
983→		treePath := filepath.ToSlash(filepath.Join(dirPathRel, relWithinDir))
984→
985→		blobHash, mode, blobErr := createRedactedBlobFromFile(repo, path, treePath)
986→		if blobErr != nil {
987→			return fmt.Errorf("failed to create blob for %s: %w", path, blobErr)
988→		}
989→		changes = append(changes, TreeChange{
990→			Path:  treePath,
991→			Entry: &object.TreeEntry{Mode: mode, Hash: blobHash},
992→		})
993→		return nil
994→	})
995→	if err != nil {
996→		return nil, fmt.Errorf("failed to walk directory %s: %w", dirPathAbs, err)
997→	}
998→	return changes, nil

