var standardMetadataFiles = map[string]bool{
	paths.TranscriptFileName:       true,
	paths.TranscriptFileNameLegacy: true,
	paths.PromptFileName:           true,
	paths.ContextFileName:          true,
	paths.SummaryFileName:          true,
